def is_valid_account_id(value):
    if not isinstance(value, str) or len(value) != 8:
        return False
    letters, digits, check = value[:3], value[3:7], value[7]
    if not letters.isalpha() or not letters.isupper():
        return False
    if not digits.isdigit() or not check.isdigit():
        return False
    expected = sum(int(d) for d in digits) % 10
    return int(check) == expected
